// ——————— EXAMES ———————
async function callClaude(prompt, maxTokens = 2000) {
  const resp = await fetch('https://api.anthropic.com/v1/messages', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: 'claude-sonnet-4-20250514',
      max_tokens: maxTokens,
      system: 'Responda SOMENTE com JSON puro válido. Sem markdown, sem texto fora do JSON. Nunca use aspas duplas dentro de valores de string — use aspas simples ou reescreva a frase. Nunca insira quebras de linha dentro de valores de string.',
      messages: [{ role: 'user', content: prompt }],
    }),
  });
  if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
  const data = await resp.json();
  if (data.error) throw new Error(data.error.message);
  const raw = (data.content?.[0]?.text || '').trim();
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start === -1 || end === -1) throw new Error('JSON inválido na resposta');
  let jsonStr = raw.slice(start, end + 1);
  // Repair: sanitize newlines/tabs inside string values
  jsonStr = jsonStr.replace(/:\s*"((?:[^"\\]|\\.)*)"/g, (_, v) =>
    `: "${v.replace(/[\n\r\t]/g, ' ').replace(/ {2,}/g, ' ')}"`
  );
  return JSON.parse(jsonStr);
}

