function HemogramaForm({ onResult, onError, loading, setLoading }) {
  const [vals, setVals] = useState({});
  const [sex, setSex] = useState('M');
  const [ctx, setCtx] = useState('');

  const set = (k, v) => setVals(p => ({ ...p, [k]: v }));

  async function interpret() {
    const filled = Object.entries(vals).filter(([, v]) => v.trim()).map(([k, v]) => {
      const f = HMG_FIELDS.flatMap(g => g.fields).find(f => f.key === k);
      return `${f?.label}: ${v} ${f?.unit}`;
    }).join('\n');
    if (!filled) { onError('Preencha pelo menos um parâmetro do hemograma.'); return; }
    setLoading(true); onResult(null); onError(null);
    try {
      const r = await callClaude(
        `Hemograma. Sexo: ${sex === 'M' ? 'M' : 'F'}. Dados: ${filled}.${ctx ? ` Contexto: ${ctx}` : ''}

JSON (sem aspas duplas nos valores, sem quebras de linha):
{"gravidadeGeral":"normal|atencao|critico|emergencia","resumoClinico":"frase clinica","serieVermelha":{"status":"normal|atencao|critico","interpretacao":"frase","achados":["a1","a2"]},"serieBranca":{"status":"normal|atencao|critico","interpretacao":"frase","achados":["a1","a2"]},"plaquetas":{"status":"normal|atencao|critico","interpretacao":"frase","achados":["a1"]},"hipotesesDiagnosticas":["h1","h2","h3"],"sinaisDeAlerta":["s1","s2"],"condutasEnfermagem":["c1","c2","c3","c4"],"quandoComunicarMedico":"orientacao","monitoracao":["m1","m2","m3"],"dicaDaSupervisora":"dica pratica"}`,
        2500
      );
      onResult(r);
    } catch(e) {
      onError(`Erro ao interpretar hemograma: ${e.message}`);
    } finally { setLoading(false); }
  }

  const filledCount = Object.values(vals).filter(v => v.trim()).length;

  return (
    <div style={{ display:'flex', flexDirection:'column', gap:14 }}>
      <div className="card">
        <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:14 }}>
          <h3 style={{ fontFamily:"'Inter',sans-serif", fontSize:15, fontWeight:700 }}>🩸 Hemograma Completo</h3>
          <div style={{ display:'flex', gap:6 }}>
            {[{v:'M',l:'Masculino'},{v:'F',l:'Feminino'}].map(s => (
              <div key={s.v} onClick={() => setSex(s.v)} style={{
                padding:'5px 13px', borderRadius:7, cursor:'pointer', fontSize:12, fontWeight:600, transition:'all 0.15s',
                background: sex===s.v ? C.accentGlow : 'transparent',
                border: `1px solid ${sex===s.v ? C.accent+'55' : C.border}`,
                color: sex===s.v ? C.accent : C.muted,
              }}>{s.l}</div>
            ))}
          </div>
        </div>

        {HMG_FIELDS.map(group => (
          <div key={group.group} style={{ marginBottom:18 }}>
            <div style={{ fontSize:11, fontWeight:700, textTransform:'uppercase', letterSpacing:1, color:group.color, marginBottom:10 }}>{group.group}</div>
            <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:9 }}>
              {group.fields.map(f => (
                <div key={f.key}>
                  <label style={{ fontSize:11, color:C.muted, display:'block', marginBottom:4 }}>
                    {f.label} <span style={{ color:C.dim }}>({f.unit})</span>
                  </label>
                  <div style={{ position:'relative' }}>
                    <input
                      type="number"
                      placeholder={f.placeholder}
                      value={vals[f.key] || ''}
                      onChange={e => set(f.key, e.target.value)}
                      style={{ paddingRight:52,
                        borderColor: vals[f.key] ? group.color+'55' : undefined,
                      }}
                    />
                    <span style={{ position:'absolute', right:8, top:'50%', transform:'translateY(-50%)', fontSize:10, color:C.dim, pointerEvents:'none' }}>{f.unit}</span>
                  </div>
                  <div style={{ fontSize:10, color:C.dim, marginTop:2 }}>
                    Ref: {sex === 'M' ? f.refM : f.refF}
                  </div>
                </div>
              ))}
            </div>
          </div>
        ))}

        <div style={{ borderTop:`1px solid ${C.border}`, paddingTop:12, marginTop:4, display:'flex', flexDirection:'column', gap:9 }}>
          <input placeholder="Contexto clínico — diagnóstico, sinais, medicações em uso (opcional)" value={ctx} onChange={e => setCtx(e.target.value)} />
          <div style={{ display:'flex', alignItems:'center', gap:12 }}>
            <button className="btn btn-teal" onClick={interpret} disabled={loading || filledCount === 0}>
              {loading ? '⏳ Interpretando...' : `🔬 Interpretar Hemograma${filledCount ? ` (${filledCount} campos)` : ''}`}
            </button>
            {filledCount > 0 && (
              <button className="btn btn-ghost" onClick={() => { setVals({}); setCtx(''); }} style={{ fontSize:12 }}>↺ Limpar</button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

function HemogramaResult({ result }) {
  const s = SEV[result.gravidadeGeral] || SEV.atencao;
  const serieColor = { normal: C.ok, atencao: C.warn, critico: C.danger };

  return (
    <div className="fadeUp" style={{ display:'flex', flexDirection:'column', gap:12 }}>
      <div style={{ background:s.bg, border:`1px solid ${s.c}40`, borderRadius:14, padding:'18px 22px', display:'flex', alignItems:'center', gap:18 }}>
        <div style={{ width:52, height:52, borderRadius:13, background:s.c+'25', border:`2px solid ${s.c}`, display:'flex', alignItems:'center', justifyContent:'center', fontSize:22, fontWeight:900, color:s.c, flexShrink:0 }}>{s.icon}</div>
        <div>
          <div style={{ fontSize:10.5, color:C.muted, textTransform:'uppercase', letterSpacing:1 }}>Avaliação geral</div>
          <div style={{ fontFamily:"'Inter',sans-serif", fontSize:22, fontWeight:800, color:s.c }}>{s.label}</div>
        </div>
      </div>

      <div className="card">
        <span className="section-label" style={{ color:C.accent }}>📋 Resumo clínico</span>
        <p style={{ fontSize:14, lineHeight:1.75, color:C.text }}>{result.resumoClinico}</p>
      </div>

      <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:12 }}>
        {[
          { key:'serieVermelha', label:'🩸 Série Vermelha', c:'#FF5A7A' },
          { key:'serieBranca',   label:'🔵 Série Branca',   c:'#00C9A7' },
          { key:'plaquetas',     label:'🟣 Plaquetas',      c:'#A78BFA' },
        ].map(serie => {
          const d = result[serie.key];
          if (!d) return null;
          const sc = serieColor[d.status] || C.warn;
          return (
            <div key={serie.key} style={{ background:sc+'0D', border:`1px solid ${sc}35`, borderRadius:12, padding:'14px 16px' }}>
              <div style={{ fontSize:11, color:serie.c, fontWeight:700, textTransform:'uppercase', letterSpacing:0.8, marginBottom:6 }}>{serie.label}</div>
              <div style={{ fontSize:11.5, fontWeight:700, color:sc, marginBottom:8, background:sc+'15', borderRadius:6, padding:'3px 8px', display:'inline-block' }}>{d.status?.toUpperCase()}</div>
              <p style={{ fontSize:12.5, color:C.text, lineHeight:1.65, marginBottom:8 }}>{d.interpretacao}</p>
              {d.achados?.map((a, i) => <div key={i} style={{ fontSize:11.5, color:C.muted, marginBottom:4, paddingLeft:8, borderLeft:`2px solid ${sc}30` }}>{a}</div>)}
            </div>
          );
        })}
      </div>

      <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:12 }}>
        <div className="card">
          <span className="section-label" style={{ color:C.purple }}>🔎 Hipóteses diagnósticas</span>
          {result.hipotesesDiagnosticas?.map((h, i) => (
            <div key={i} style={{ display:'flex', alignItems:'flex-start', gap:9, marginBottom:7 }}>
              <div style={{ width:20, height:20, borderRadius:5, background:C.purpleGlow, border:`1px solid ${C.purple}35`, display:'flex', alignItems:'center', justifyContent:'center', fontSize:10, fontWeight:700, color:C.purple, flexShrink:0, marginTop:1 }}>{i+1}</div>
              <div style={{ fontSize:13, color:C.text, lineHeight:1.6 }}>{h}</div>
            </div>
          ))}
        </div>
        <div className="card" style={{ borderColor:`${C.danger}25` }}>
          <span className="section-label" style={{ color:C.danger }}>🚨 Sinais de alerta</span>
          {result.sinaisDeAlerta?.map((a, i) => <div key={i} style={{ fontSize:13, color:C.text, marginBottom:6, paddingLeft:10, borderLeft:`2px solid ${C.danger}40` }}>{a}</div>)}
        </div>
      </div>

      <div className="card" style={{ borderColor:`${C.accent}30` }}>
        <span className="section-label" style={{ color:C.accent }}>✅ Condutas de enfermagem</span>
        {result.condutasEnfermagem?.map((c, i) => (
          <div key={i} style={{ display:'flex', alignItems:'flex-start', gap:10, marginBottom:9 }}>
            <div style={{ width:24, height:24, borderRadius:7, background:C.accentGlow, border:`1px solid ${C.accent}35`, display:'flex', alignItems:'center', justifyContent:'center', fontSize:11, fontWeight:700, color:C.accent, flexShrink:0 }}>{i+1}</div>
            <div style={{ fontSize:13.5, color:C.text, lineHeight:1.6, paddingTop:3 }}>{c}</div>
          </div>
        ))}
      </div>

      <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:12 }}>
        <div className="card">
          <span className="section-label" style={{ color:C.purple }}>📞 Quando acionar médico</span>
          <p style={{ fontSize:13, color:C.muted, lineHeight:1.65 }}>{result.quandoComunicarMedico}</p>
        </div>
        <div className="card">
          <span className="section-label" style={{ color:C.warn }}>👁 Monitorização</span>
          {result.monitoracao?.map((m, i) => <div key={i} style={{ fontSize:13, color:C.muted, marginBottom:5 }}>• {m}</div>)}
        </div>
      </div>

      <div style={{ background:`linear-gradient(135deg,${C.card},${C.goldGlow})`, border:`1px solid ${C.gold}35`, borderRadius:14, padding:'18px 22px' }}>
        <div style={{ fontSize:11, color:C.gold, fontWeight:700, textTransform:'uppercase', letterSpacing:1, marginBottom:9 }}>⭐ Dica da supervisora</div>
        <p style={{ fontSize:14, color:C.text, lineHeight:1.7, fontStyle:'italic' }}>"{result.dicaDaSupervisora}"</p>
        <div style={{ fontSize:11.5, color:C.muted, marginTop:9 }}>— Andreia Yamaguti · Supervisora UTI</div>
      </div>
    </div>
  );
}

function ExamesSection() {
  const [mode, setMode] = useState('avulso'); // 'avulso' | 'hemograma'
  const [exam, setExam] = useState('');
  const [val, setVal] = useState('');
  const [ctx, setCtx] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [hmgResult, setHmgResult] = useState(null);
  const [err, setErr] = useState(null);

  const COMMON = ['Potássio (K+)', 'Sódio (Na+)', 'Hemoglobina', 'Gasometria arterial', 'Creatinina', 'Lactato', 'Glicemia', 'Plaquetas', 'PCR', 'INR', 'Ureia', 'TGO/TGP'];

  async function interpret() {
    setLoading(true); setResult(null); setErr(null);
    try {
      const r = await callClaude(
        `Exame: ${exam}${val ? `. Valor: ${val}` : ''}${ctx ? `. Contexto: ${ctx}` : ''}

Retorne JSON com estes campos (sem aspas duplas dentro dos valores, sem quebras de linha):
{"exame":"nome","valorEncontrado":"valor","valorReferencia":"referencia","gravidade":"normal|atencao|critico|emergencia","interpretacao":"frase clinica pratica","riscos":["r1","r2"],"causasProvaveis":["c1","c2"],"sinaisClinicosEsperados":["s1","s2"],"condutasEnfermagem":["cond1","cond2","cond3","cond4"],"quandoComunicarMedico":"orientacao","prioridade":"baixa|media|alta|emergencia","monitoracao":["m1","m2","m3"],"dicaDaSupervisora":"dica pratica"}`,
        2000
      );
      setResult(r);
    } catch(e) {
      setErr(`Erro ao interpretar: ${e.message}. Tente novamente.`);
    } finally { setLoading(false); }
  }

  const s = result ? (SEV[result.gravidade] || SEV.atencao) : null;

  return (
    <div style={{ display:'flex', flexDirection:'column', gap:18, maxWidth:860 }}>
      {/* Mode selector */}
      <div style={{ display:'flex', gap:8 }}>
        {[
          { id:'avulso',    label:'🧪 Exame avulso',        desc:'Qualquer exame isolado' },
          { id:'hemograma', label:'🩸 Hemograma Completo',   desc:'CBC com todas as séries' },
        ].map(m => (
          <div key={m.id} onClick={() => { setMode(m.id); setResult(null); setHmgResult(null); setErr(null); }} style={{
            flex:1, padding:'12px 18px', borderRadius:12, cursor:'pointer', transition:'all 0.18s',
            background: mode===m.id ? C.accentGlow : C.card,
            border: `1px solid ${mode===m.id ? C.accent+'55' : C.border}`,
          }}>
            <div style={{ fontSize:14, fontWeight:700, color: mode===m.id ? C.accent : C.text }}>{m.label}</div>
            <div style={{ fontSize:11.5, color:C.muted, marginTop:2 }}>{m.desc}</div>
          </div>
        ))}
      </div>

      {/* Avulso mode */}
      {mode === 'avulso' && (
        <div className="card">
          <h3 style={{ fontFamily:"'Inter',sans-serif", fontSize:16, fontWeight:700, marginBottom:15 }}>Qual exame deseja interpretar?</h3>
          <div style={{ display:'flex', flexWrap:'wrap', gap:7, marginBottom:16 }}>
            {COMMON.map(e => <span key={e} className={`chip${exam===e?' sel':''}`} onClick={() => setExam(e)}>{e}</span>)}
          </div>
          <div style={{ display:'flex', flexDirection:'column', gap:9 }}>
            <input placeholder="Nome do exame (ex: Potássio, Gasometria arterial, INR...)" value={exam} onChange={e => setExam(e.target.value)} />
            <input placeholder="Valor encontrado (ex: 6.8 mEq/L, pH 7.18, Hb 6.2...)" value={val} onChange={e => setVal(e.target.value)} />
            <input placeholder="Contexto clínico (ex: paciente em oligúria, DRC, uso de iECA — opcional)" value={ctx} onChange={e => setCtx(e.target.value)} />
            <button className="btn btn-teal" onClick={interpret} disabled={loading || !exam.trim()} style={{ alignSelf:'flex-start' }}>
              {loading ? '⏳ Interpretando...' : '🔍 Interpretar Resultado'}
            </button>
          </div>
        </div>
      )}

      {/* Hemograma mode */}
      {mode === 'hemograma' && (
        <HemogramaForm
          onResult={setHmgResult}
          onError={setErr}
          loading={loading}
          setLoading={setLoading}
        />
      )}

      {err && <ErrorBox msg={err} />}
      {loading && <Loader msg={mode==='hemograma' ? 'Interpretando hemograma completo com raciocínio hematológico...' : 'Analisando resultado clínico com raciocínio de UTI...'} />}

      {/* Avulso result */}
      {mode === 'avulso' && result && s && (
        <div className="fadeUp" style={{ display:'flex', flexDirection:'column', gap:12 }}>
          <div style={{ background:s.bg, border:`1px solid ${s.c}40`, borderRadius:14, padding:'18px 22px', display:'flex', alignItems:'center', gap:18 }}>
            <div style={{ width:52, height:52, borderRadius:13, background:s.c+'25', border:`2px solid ${s.c}`, display:'flex', alignItems:'center', justifyContent:'center', fontSize:22, fontWeight:900, color:s.c, flexShrink:0 }}>{s.icon}</div>
            <div>
              <div style={{ fontSize:10.5, color:C.muted, textTransform:'uppercase', letterSpacing:1 }}>Gravidade</div>
              <div style={{ fontFamily:"'Inter',sans-serif", fontSize:24, fontWeight:800, color:s.c }}>{s.label}</div>
            </div>
            <div style={{ marginLeft:'auto', textAlign:'right' }}>
              <div style={{ fontSize:11, color:C.muted }}>Valor encontrado</div>
              <div className="num" style={{ fontSize:20, fontWeight:500, color:C.text }}>{result.valorEncontrado}</div>
              <div style={{ fontSize:11.5, color:C.muted }}>Ref: {result.valorReferencia}</div>
            </div>
          </div>
          <div className="card">
            <span className="section-label" style={{ color:C.accent }}>📋 Interpretação clínica</span>
            <p style={{ fontSize:14, lineHeight:1.75, color:C.text }}>{result.interpretacao}</p>
          </div>
          <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:12 }}>
            <div className="card">
              <span className="section-label" style={{ color:C.danger }}>⚠ Riscos</span>
              {result.riscos?.map((r, i) => <div key={i} style={{ fontSize:13, color:C.muted, marginBottom:6, paddingLeft:10, borderLeft:`2px solid ${C.danger}35` }}>{r}</div>)}
            </div>
            <div className="card">
              <span className="section-label" style={{ color:C.warn }}>🔍 Causas prováveis</span>
              {result.causasProvaveis?.map((c, i) => <div key={i} style={{ fontSize:13, color:C.muted, marginBottom:6, paddingLeft:10, borderLeft:`2px solid ${C.warn}35` }}>{c}</div>)}
            </div>
          </div>
          <div className="card" style={{ borderColor:`${C.accent}30` }}>
            <span className="section-label" style={{ color:C.accent }}>✅ Condutas de enfermagem</span>
            {result.condutasEnfermagem?.map((c, i) => (
              <div key={i} style={{ display:'flex', alignItems:'flex-start', gap:10, marginBottom:9 }}>
                <div style={{ width:24, height:24, borderRadius:7, background:C.accentGlow, border:`1px solid ${C.accent}35`, display:'flex', alignItems:'center', justifyContent:'center', fontSize:11, fontWeight:700, color:C.accent, flexShrink:0 }}>{i+1}</div>
                <div style={{ fontSize:13.5, color:C.text, lineHeight:1.6, paddingTop:3 }}>{c}</div>
              </div>
            ))}
          </div>
          <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:12 }}>
            <div className="card">
              <span className="section-label" style={{ color:C.purple }}>📞 Quando acionar médico</span>
              <p style={{ fontSize:13, color:C.muted, lineHeight:1.65 }}>{result.quandoComunicarMedico}</p>
            </div>
            <div className="card">
              <span className="section-label" style={{ color:C.warn }}>👁 Monitorização</span>
              {result.monitoracao?.map((m, i) => <div key={i} style={{ fontSize:13, color:C.muted, marginBottom:5 }}>• {m}</div>)}
            </div>
          </div>
          <div style={{ background:`linear-gradient(135deg,${C.card},${C.goldGlow})`, border:`1px solid ${C.gold}35`, borderRadius:14, padding:'18px 22px' }}>
            <div style={{ fontSize:11, color:C.gold, fontWeight:700, textTransform:'uppercase', letterSpacing:1, marginBottom:9 }}>⭐ Dica da supervisora</div>
            <p style={{ fontSize:14, color:C.text, lineHeight:1.7, fontStyle:'italic' }}>"{result.dicaDaSupervisora}"</p>
            <div style={{ fontSize:11.5, color:C.muted, marginTop:9 }}>— Andreia Yamaguti · Supervisora UTI</div>
          </div>
        </div>
      )}

      {/* Hemograma result */}
      {mode === 'hemograma' && hmgResult && <HemogramaResult result={hmgResult} />}
    </div>
  );
}

// ——————— MODO PLANTÃO ———————
function PlantaoSection() {
  const [sit, setSit] = useState('');
  const [ctx, setCtx] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [err, setErr] = useState(null);

  const SITS = [
    '🧠 Rebaixamento do nível de consciência',
    '📉 Hipotensão',
    '📈 Hipertensão grave',
    '💗 Taquicardia',
    '💔 Bradicardia',
    '🌡️ Febre alta',
    '💧 Oligúria / Anúria',
    '🫁 Dessaturação',
    '🩸 Hipoglicemia',
    '😤 Agitação / Delirium',
    '🩺 Piora respiratória',
    '💊 Reação a medicamento',
  ];

  async function assess() {
    setLoading(true); setResult(null); setErr(null);
    try {
      const r = await callClaude(
        `Situacao clinica: ${sit}${ctx ? `. Contexto: ${ctx}` : ''}

JSON (sem aspas duplas nos valores, sem quebras de linha):
{"situacao":"descricao","prioridade":"imediata|alta|media","riscoIminente":true,"mensagemRapida":"frase direta","primeirosPasso":["p1","p2","p3","p4"],"oQueAvaliar":["a1","a2","a3"],"oQueMonitorar":["m1","m2","m3"],"sinaisDeAlerta":["s1","s2","s3"],"quandoEscalar":"orientacao"}`,
        2000
      );
      setResult(r);
    } catch(e) { setErr(`Erro: ${e.message}`); }
    finally { setLoading(false); }
  }

  const isEmergency = result?.riscoIminente;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 18, maxWidth: 820 }}>
      <div style={{ background: C.dangerGlow, border: `1px solid ${C.danger}40`, borderRadius: 12, padding: '11px 16px', fontSize: 13, color: C.danger, display: 'flex', alignItems: 'center', gap: 8 }}>
        <span>🚨</span>
        <span>Modo Plantão: suporte ao raciocínio clínico. <strong>Em emergência real, acione o médico imediatamente.</strong></span>
      </div>

      <div className="card">
        <h3 style={{ fontFamily: "'Inter',sans-serif", fontSize: 16, fontWeight: 700, marginBottom: 15 }}>Qual é a situação clínica?</h3>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 7, marginBottom: 16 }}>
          {SITS.map(s => (
            <span key={s} className={`chip danger${sit === s ? ' sel' : ''}`} onClick={() => setSit(s)} style={{ fontSize: 12 }}>{s}</span>
          ))}
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 9 }}>
          <input placeholder="Ou descreva a situação..." value={sit} onChange={e => setSit(e.target.value)} />
          <textarea placeholder="Contexto: sinais vitais, tempo de início, medicações, histórico relevante..." value={ctx} onChange={e => setCtx(e.target.value)} rows={3} />
          <button className="btn btn-red" onClick={assess} disabled={loading || !sit} style={{ alignSelf: 'flex-start' }}>
            {loading ? '⏳ Avaliando...' : '🚨 Avaliar Situação'}
          </button>
        </div>
      </div>

      {err && <ErrorBox msg={err} />}
      {loading && <Loader color={C.danger} msg="Avaliando situação clínica com raciocínio de UTI..." />}

      {result && (
        <div className="fadeUp" style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          <div style={{ background: isEmergency ? C.dangerGlow : C.warnGlow, border: `1px solid ${isEmergency ? C.danger : C.warn}45`, borderRadius: 14, padding: '18px 22px' }}>
            <div style={{ fontSize: 11, color: C.muted, marginBottom: 5 }}>{result.situacao}</div>
            <div style={{ fontFamily: "'Inter',sans-serif", fontSize: 22, fontWeight: 800, color: isEmergency ? C.danger : C.warn }}>
              {isEmergency ? '🚨 RISCO IMINENTE' : `⚠ Prioridade: ${result.prioridade?.toUpperCase()}`}
            </div>
            <div style={{ fontSize: 14.5, color: C.text, marginTop: 10, borderTop: `1px solid ${C.border}`, paddingTop: 10, fontWeight: 500 }}>
              {result.mensagemRapida}
            </div>
          </div>

          <div className="card" style={{ borderColor: `${C.danger}30` }}>
            <span className="section-label" style={{ color: C.danger }}>⚡ Primeiros passos — AGORA</span>
            {result.primeirosPasso?.map((p, i) => (
              <div key={i} style={{ display: 'flex', alignItems: 'flex-start', gap: 10, marginBottom: 9 }}>
                <div style={{ width: 26, height: 26, borderRadius: 7, background: C.dangerGlow, border: `1px solid ${C.danger}35`, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 11, fontWeight: 700, color: C.danger, flexShrink: 0 }}>{i + 1}</div>
                <div style={{ fontSize: 13.5, color: C.text, lineHeight: 1.6, paddingTop: 4 }}>{p}</div>
              </div>
            ))}
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
            <div className="card">
              <span className="section-label" style={{ color: C.accent }}>🔍 O que avaliar</span>
              {result.oQueAvaliar?.map((a, i) => <div key={i} style={{ fontSize: 13, color: C.muted, marginBottom: 6, paddingLeft: 10, borderLeft: `2px solid ${C.accent}35` }}>{a}</div>)}
            </div>
            <div className="card">
              <span className="section-label" style={{ color: C.warn }}>👁 O que monitorar</span>
              {result.oQueMonitorar?.map((m, i) => <div key={i} style={{ fontSize: 13, color: C.muted, marginBottom: 6, paddingLeft: 10, borderLeft: `2px solid ${C.warn}35` }}>{m}</div>)}
            </div>
          </div>

          <div className="card" style={{ borderColor: `${C.danger}30` }}>
            <span className="section-label" style={{ color: C.danger }}>🔴 Sinais de alerta — escalar imediatamente se:</span>
            {result.sinaisDeAlerta?.map((s, i) => <div key={i} style={{ fontSize: 13, color: C.text, marginBottom: 5 }}>• {s}</div>)}
          </div>

          <div className="card" style={{ borderColor: `${C.purple}30` }}>
            <span className="section-label" style={{ color: C.purple }}>📞 Quando acionar médico / equipe</span>
            <p style={{ fontSize: 13.5, color: C.text, lineHeight: 1.65 }}>{result.quandoEscalar}</p>
          </div>
        </div>
      )}
    </div>
  );
}

