function ProtocolosSection() {
  const [sel, setSel] = useState(null);
  const p = PROTS.find(x => x.id === sel);
  return (
    <div style={{ display: 'flex', gap: 18, maxWidth: 940, height: 'calc(100vh - 180px)' }}>
      <div style={{ width: 270, minWidth: 270, display: 'flex', flexDirection: 'column', gap: 8, overflowY: 'auto' }}>
        {PROTS.map(x => (
          <div key={x.id} onClick={() => setSel(x.id)} style={{
            background: sel === x.id ? x.c + '12' : C.card,
            border: `1px solid ${sel === x.id ? x.c + '50' : C.border}`,
            borderRadius: 11, padding: '13px 15px', cursor: 'pointer', transition: 'all 0.15s',
          }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
              <span style={{ fontSize: 20 }}>{x.icon}</span>
              <div>
                <div style={{ fontSize: 13, fontWeight: 600, color: sel === x.id ? x.c : C.text }}>{x.title}</div>
                <div style={{ fontSize: 11, color: C.muted, marginTop: 2 }}>{x.cat}</div>
              </div>
            </div>
          </div>
        ))}
      </div>

      <div style={{ flex: 1, overflowY: 'auto' }}>
        {p ? (
          <div className="card fadeUp" style={{ borderColor: `${p.c}30` }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 20 }}>
              <span style={{ fontSize: 34 }}>{p.icon}</span>
              <div>
                <div style={{ fontSize: 10.5, color: C.muted, textTransform: 'uppercase', letterSpacing: 1 }}>Protocolo rápido</div>
                <h2 style={{ fontFamily: "'Inter',sans-serif", fontSize: 20, fontWeight: 800, color: p.c }}>{p.title}</h2>
              </div>
            </div>
            <div style={{ background: p.c + '10', border: `1px solid ${p.c}30`, borderRadius: 8, padding: '9px 13px', fontSize: 13, color: p.c, fontWeight: 600, marginBottom: 18 }}>
              ⏱ O que fazer nos primeiros minutos
            </div>
            {p.steps.map((step, i) => (
              <div key={i} style={{ display: 'flex', alignItems: 'flex-start', gap: 12, marginBottom: 13, paddingBottom: 13, borderBottom: i < p.steps.length - 1 ? `1px solid ${C.border}` : 'none' }}>
                <div className="num" style={{ width: 30, height: 30, borderRadius: 8, background: p.c + '18', border: `1px solid ${p.c}35`, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 12, fontWeight: 500, color: p.c, flexShrink: 0 }}>
                  {String(i + 1).padStart(2, '0')}
                </div>
                <div style={{ fontSize: 13.5, color: C.text, lineHeight: 1.65, paddingTop: 5 }}>{step}</div>
              </div>
            ))}
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: '100%', color: C.dim, gap: 12 }}>
            <div style={{ fontSize: 48 }}>📋</div>
            <div style={{ fontSize: 14 }}>Selecione um protocolo para visualizar</div>
          </div>
        )}
      </div>
    </div>
  );
}

// ——————— EVOLUÇÃO ———————
function EvolucaoSection() {
  const [sector, setSector] = useState('');
  const [neuro, setNeuro] = useState('');
  const [vent, setVent] = useState('');
  const [devices, setDevices] = useState([]);
  const [extra, setExtra] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState('');
  const [err, setErr] = useState(null);
  const [copied, setCopied] = useState(false);

  const toggle = (d) => setDevices(p => p.includes(d) ? p.filter(x => x !== d) : [...p, d]);

  const SECTORS = ['UTI Adulto', 'Pronto-Socorro', 'Clínica Médica', 'Clínica Cirúrgica', 'Oncologia'];
  const NEUROS  = ['Sedado profundo / RASS -3 a -4', 'Sedação leve / RASS -1 a -2', 'Acordado e orientado (A+O3)', 'Rebaixado / desorientado', 'Agitado psicomotor'];
  const VENTS   = ['VM Controlado (VCI/PCV)', 'VM Pressão de Suporte (PSV)', 'VNI (CPAP/BiPAP)', 'Cateter nasal O2', 'Máscara simples O2', 'Máscara não-reinalante', 'Ar ambiente'];
  const DEVS    = ['TOT', 'TQT', 'CVC', 'SNE', 'SVD', 'PAI', 'PICC', 'Dreno torácico', 'Dreno abdominal'];

  async function generate() {
    setLoading(true); setResult(''); setErr(null);
    try {
      const r = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: 'claude-sonnet-4-20250514',
          max_tokens: 2000,
          system: 'Você é enfermeira supervisora de UTI. Gere evoluções de enfermagem profissionais, técnicas e objetivas.',
          messages: [{ role: 'user', content: `Gere uma evolução de enfermagem profissional para SAE. Linguagem técnica de UTI. 1ª pessoa do plural. Máximo 200 palavras. Texto corrido sem tópicos.

Setor: ${sector || 'UTI Adulto'}
Estado neurológico: ${neuro || 'não informado'}
Suporte ventilatório: ${vent || 'não informado'}
Dispositivos: ${devices.length ? devices.join(', ') : 'nenhum'}
${extra ? `Dados adicionais: ${extra}` : ''}` }],
        }),
      });
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      const d = await r.json();
      if (d.error) throw new Error(d.error.message);
      setResult(d.content?.[0]?.text || '');
    } catch(e) { setErr(`Erro: ${e.message}`); }
    finally { setLoading(false); }
  }

  function copy() {
    navigator.clipboard.writeText(result);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 18, maxWidth: 820 }}>
      <div className="card">
        <h3 style={{ fontFamily: "'Inter',sans-serif", fontSize: 16, fontWeight: 700, marginBottom: 18 }}>Configurar evolução</h3>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 15 }}>
          {[
            { label: 'Setor', items: SECTORS, state: sector, set: setSector, single: true },
            { label: 'Estado neurológico', items: NEUROS, state: neuro, set: setNeuro, single: true },
            { label: 'Suporte ventilatório', items: VENTS, state: vent, set: setVent, single: true },
          ].map(g => (
            <div key={g.label}>
              <span className="label">{g.label}</span>
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 7 }}>
                {g.items.map(i => (
                  <span key={i} className={`chip${g.state === i ? ' sel' : ''}`} onClick={() => g.set(g.state === i ? '' : i)}>{i}</span>
                ))}
              </div>
            </div>
          ))}
          <div>
            <span className="label">Dispositivos invasivos (múltiplos)</span>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 7 }}>
              {DEVS.map(d => <span key={d} className={`chip${devices.includes(d) ? ' sel' : ''}`} onClick={() => toggle(d)}>{d}</span>)}
            </div>
          </div>
          <div>
            <span className="label">Informações adicionais (opcional)</span>
            <textarea placeholder="Ex: paciente em pós-op de laparotomia, em uso de noradrenalina 0.2mcg/kg/min, balanço hídrico negativo..." value={extra} onChange={e => setExtra(e.target.value)} rows={2} />
          </div>
          <button className="btn btn-teal" onClick={generate} disabled={loading || !sector} style={{ alignSelf: 'flex-start' }}>
            {loading ? '⏳ Gerando...' : '✍️ Gerar Evolução'}
          </button>
        </div>
      </div>

      {err && <ErrorBox msg={err} />}
      {loading && <Loader msg="Gerando evolução de enfermagem profissional..." />}

      {result && (
        <div className="card fadeUp" style={{ borderColor: `${C.accent}30` }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 14 }}>
            <span className="section-label" style={{ color: C.accent }}>✅ Evolução gerada</span>
            <button className="btn btn-ghost" onClick={copy} style={{ padding: '7px 14px', fontSize: 12 }}>
              {copied ? '✓ Copiado!' : '📋 Copiar texto'}
            </button>
          </div>
          <div style={{ background: C.surface, borderRadius: 9, padding: 18, fontSize: 14, color: C.text, lineHeight: 1.85, border: `1px solid ${C.border}` }}>
            {result}
          </div>
          <div style={{ fontSize: 11.5, color: C.dim, marginTop: 10 }}>
            ⚠ Revise e adapte ao paciente real antes de registrar no prontuário.
          </div>
        </div>
      )}
    </div>
  );
}

