function ScaleWidget({ scale }) {
  const [sel, setSel] = useState({});
  const cc = ECAT_COLOR[scale.cat] || C.accent;

  let result = null;
  if (scale.type === 'calculator') {
    if (scale.groups.every(g => sel[g.key] !== undefined)) {
      const score = scale.groups.reduce((s, g) => s + (sel[g.key] || 0), 0);
      result = { score, interp: scale.interpret(score) };
    }
  } else if (scale.type === 'single') {
    if (sel.value !== undefined) result = { score: sel.value, interp: scale.interpret(sel.value) };
  } else if (scale.type === 'checklist') {
    const interp = scale.interpret(sel);
    if (interp) result = { interp };
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
      <div className="card"><p style={{ fontSize: 13.5, color: C.muted, lineHeight: 1.75 }}>{scale.desc}</p></div>

      {scale.type === 'calculator' && scale.groups.map(g => (
        <div key={g.key} className="card">
          <span className="section-label" style={{ color: cc }}>{g.label}</span>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
            {g.options.map(opt => (
              <div key={opt.score} onClick={() => setSel(p => ({ ...p, [g.key]: opt.score }))} style={{
                padding: '10px 14px', borderRadius: 9, cursor: 'pointer', transition: 'all 0.15s',
                border: `1px solid ${sel[g.key] === opt.score ? cc + '60' : C.border}`,
                background: sel[g.key] === opt.score ? cc + '14' : C.surface,
                display: 'flex', alignItems: 'center', justifyContent: 'space-between',
              }}>
                <span style={{ fontSize: 13, color: sel[g.key] === opt.score ? C.text : C.muted }}>{opt.label}</span>
                <span className="num" style={{ fontSize: 13, fontWeight: 600, color: sel[g.key] === opt.score ? cc : C.dim }}>{opt.score}</span>
              </div>
            ))}
          </div>
        </div>
      ))}

      {scale.type === 'single' && (
        <div className="card">
          <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
            {scale.options.map(opt => (
              <div key={opt.score} onClick={() => setSel({ value: opt.score })} style={{
                padding: '11px 14px', borderRadius: 9, cursor: 'pointer', transition: 'all 0.15s',
                border: `1px solid ${sel.value === opt.score ? opt.c + '65' : C.border}`,
                background: sel.value === opt.score ? opt.c + '14' : C.surface,
              }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                  <span className="num" style={{ fontSize: 14, fontWeight: 700, color: opt.c, minWidth: 36, textAlign: 'center' }}>{opt.score > 0 ? '+' : ''}{opt.score}</span>
                  <div>
                    <div style={{ fontSize: 13, fontWeight: 600, color: sel.value === opt.score ? C.text : C.muted }}>{opt.label}</div>
                    <div style={{ fontSize: 11.5, color: C.muted, marginTop: 2 }}>{opt.desc}</div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {scale.type === 'checklist' && (
        <div className="card">
          <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
            {scale.items.map(item => (
              <div key={item.key} style={{ padding: '12px 14px', background: C.surface, borderRadius: 9, border: `1px solid ${C.border}` }}>
                <div style={{ display: 'flex', alignItems: 'flex-start', gap: 12 }}>
                  <div style={{ display: 'flex', gap: 6, flexShrink: 0, marginTop: 2 }}>
                    {[{v:true,l:'Sim'},{v:false,l:'Não'}].map(btn => (
                      <div key={btn.l} onClick={() => setSel(p => ({ ...p, [item.key]: btn.v }))} style={{
                        padding: '4px 11px', borderRadius: 6, cursor: 'pointer', fontSize: 12, fontWeight: 600, transition: 'all 0.15s',
                        border: `1px solid ${sel[item.key] === btn.v ? (btn.v ? C.danger : C.ok) + '60' : C.border}`,
                        background: sel[item.key] === btn.v ? (btn.v ? C.danger : C.ok) + '15' : 'transparent',
                        color: sel[item.key] === btn.v ? (btn.v ? C.danger : C.ok) : C.muted,
                      }}>{btn.l}</div>
                    ))}
                  </div>
                  <div>
                    <div style={{ fontSize: 13, fontWeight: 600, color: C.text }}>{item.label}</div>
                    <div style={{ fontSize: 12, color: C.muted, marginTop: 3, lineHeight: 1.55 }}>{item.desc}</div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {result && result.interp && (
        <div className="fadeUp" style={{
          background: result.interp.color + '16', border: `1px solid ${result.interp.color}45`,
          borderRadius: 14, padding: '16px 22px', display: 'flex', alignItems: 'center', gap: 18,
        }}>
          {result.score !== undefined && (
            <div style={{ textAlign: 'center', flexShrink: 0 }}>
              <div style={{ fontSize: 10, color: C.muted, textTransform: 'uppercase', letterSpacing: 1 }}>{scale.scoreLabel}</div>
              <div className="num" style={{ fontSize: 40, fontWeight: 700, color: result.interp.color, lineHeight: 1 }}>{result.score > 0 && scale.type === 'single' ? '+' : ''}{result.score}</div>
            </div>
          )}
          <div style={{ fontFamily: "'Inter',sans-serif", fontSize: 18, fontWeight: 800, color: result.interp.color }}>{result.interp.label}</div>
        </div>
      )}

      {Object.keys(sel).length > 0 && (
        <button className="btn btn-ghost" onClick={() => setSel({})} style={{ alignSelf: 'flex-start' }}>↺ Limpar calculadora</button>
      )}

      <div style={{ background:`linear-gradient(135deg,${C.card},${C.goldGlow})`, border:`1px solid ${C.gold}35`, borderRadius:14, padding:'16px 22px' }}>
        <div style={{ fontSize:11, color:C.gold, fontWeight:700, textTransform:'uppercase', letterSpacing:1, marginBottom:8 }}>⭐ Dica da supervisora</div>
        <p style={{ fontSize:13.5, color:C.text, lineHeight:1.75, fontStyle:'italic' }}>"{scale.dica}"</p>
        <div style={{ fontSize:11, color:C.muted, marginTop:8 }}>— Andreia Yamaguti · Supervisora UTI</div>
      </div>
    </div>
  );
}

function EscalasSection() {
  const [sel, setSel] = useState('glasgow');
  const scale = SCALES_DATA.find(s => s.id === sel);
  return (
    <div style={{ display:'flex', gap:16, height:'calc(100vh - 180px)' }}>
      <div style={{ width:210, minWidth:210, display:'flex', flexDirection:'column', gap:7, overflowY:'auto' }}>
        {SCALES_DATA.map(s => {
          const c = ECAT_COLOR[s.cat] || C.accent;
          return (
            <div key={s.id} onClick={() => setSel(s.id)} style={{
              background: sel === s.id ? c + '12' : C.card,
              border: `1px solid ${sel === s.id ? c + '50' : C.border}`,
              borderRadius:11, padding:'13px 14px', cursor:'pointer', transition:'all 0.15s',
            }}>
              <div style={{ fontSize:13.5, fontWeight:600, color: sel === s.id ? c : C.text, marginBottom:4 }}>{s.name}</div>
              <span style={{ background: c+'20', color:c, borderRadius:5, padding:'2px 7px', fontSize:10.5, fontWeight:700 }}>{s.cat}</span>
            </div>
          );
        })}
      </div>
      <div style={{ flex:1, overflowY:'auto' }}>
        {scale && (
          <div className="fadeUp">
            <h2 style={{ fontFamily:"'Inter',sans-serif", fontSize:20, fontWeight:800, color: ECAT_COLOR[scale.cat]||C.accent, marginBottom:14 }}>{scale.name}</h2>
            <ScaleWidget key={scale.id} scale={scale} />
          </div>
        )}
      </div>
    </div>
  );
}

